SELECT COUNT(*)
FROM t_query_template
WHERE data_source_id = #{dataSourceId}
AND status = #{status}

SELECT template_code
FROM t_query_template
WHERE data_source_id = #{dataSourceId}
AND status = #{status}
ORDER BY template_code
LIMIT #{limit}

mapper.update:
UPDATE t_query_template
SET template_name = #{next.templateName}, description = #{next.description},
    data_source_id = #{next.dataSourceId}, current_version_no = #{next.currentVersionNo},
    version = version + 1, updated_by = #{next.updatedBy}, update_time = #{next.updateTime}
WHERE template_id = #{row.templateId} AND version = #{row.version}
    AND current_version_no = #{row.currentVersionNo}

UPDATE t_query_template
SET status = #{status}, version = version + 1, updated_by = #{updatedBy}, update_time = #{updateTime}
WHERE template_id = #{row.templateId} AND version = #{row.version} AND status = #{row.status}
